import { useSelector } from 'react-redux';
import { TransactionMeta } from '@metamask/transaction-controller';
import {
  Box,
  BoxAlignItems,
  BoxFlexDirection,
  BoxJustifyContent,
  Button,
  ButtonIcon,
  ButtonIconSize,
  ButtonVariant,
  IconName,
  Text,
  TextColor,
  TextVariant,
  Skeleton,
} from '@metamask/design-system-react';
import {
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalFooter,
  AvatarToken,
  AvatarTokenSize,
} from '../../../components/component-library';

import { EditGasModes } from '../../../../shared/constants/gas';
import { getMaximumGasTotalInHexWei } from '../../../../shared/lib/gas.utils';
import {
  getAppIsLoading,
  getSelectedAccount,
  getShouldShowFiat,
} from '../../../selectors';
import { useI18nContext } from '../../../hooks/useI18nContext';
import { useTransactionModalContext } from '../../../contexts/transaction-modal';
import { isBalanceSufficient } from '../send-utils/send.utils';
import {
  GasFeeModalContextProvider,
  GasFeeModalWrapper,
  useGasFeeModalContext,
} from '../context/gas-fee-modal';
import { ConfirmInfoRow } from '../../../components/app/confirm/info/row';
import GasTiming from '../components/gas-timing/gas-timing.component';
import {
  selectNetworkConfigurationByChainId,
  type NetworkConfigurationsByChainIdState,
} from '../../../../shared/lib/selectors/networks';
import { CHAIN_ID_TOKEN_IMAGE_MAP } from '../../../../shared/constants/network';
import { ConfirmInfoSection } from '../../../components/app/confirm/info/row/section';
import { useEIP1559TxFees } from '../components/confirm/info/hooks/useEIP1559TxFees';
import { useFeeCalculations } from '../components/confirm/info/hooks/useFeeCalculations';
import { useCancelSpeedupGasState } from '../hooks/useCancelSpeedupGasState';
import { useCancelSpeedupInitialGas } from '../hooks/useCancelSpeedupInitialGas';
import { CancelSpeedupErrorToast } from '../components/cancel-speedup-toast/cancel-speedup-error-toast';
import { useCancelSpeedupActions } from '../hooks/useCancelSpeedupActions';

type EditGasButtonProps = {
  onClick: () => void;
};

const EditGasButton = ({ onClick }: EditGasButtonProps) => {
  const t = useI18nContext();
  return (
    <ButtonIcon
      size={ButtonIconSize.Sm}
      ariaLabel={t('edit')}
      iconName={IconName.Edit}
      onClick={onClick}
      data-testid="edit-gas-fee-icon"
      className="text-primary-default"
    />
  );
};

type NetworkFeeRowProps = {
  estimatedFeeNative: string;
  estimatedFeeFiat: string;
  showFiat: boolean;
  onEdit: () => void;
  chainId: string;
};

const NetworkFeeRow = ({
  estimatedFeeNative,
  estimatedFeeFiat,
  showFiat,
  onEdit,
  chainId,
}: NetworkFeeRowProps) => {
  const t = useI18nContext();

  const networkConfiguration = useSelector(
    (state: NetworkConfigurationsByChainIdState) =>
      selectNetworkConfigurationByChainId(state, chainId),
  );

  const source =
    CHAIN_ID_TOKEN_IMAGE_MAP[chainId as keyof typeof CHAIN_ID_TOKEN_IMAGE_MAP];

  const { nativeCurrency } = networkConfiguration ?? {};

  return (
    <ConfirmInfoRow
      label={t('networkFee')}
      tooltip={t('estimatedFeeTooltip')}
      data-testid="edit-gas-fees-row"
    >
      <Box
        flexDirection={BoxFlexDirection.Row}
        justifyContent={BoxJustifyContent.Between}
        alignItems={BoxAlignItems.Center}
        className="flex"
      >
        <EditGasButton onClick={onEdit} />
        <Box
          flexDirection={BoxFlexDirection.Row}
          alignItems={BoxAlignItems.Center}
          gap={1}
          className="flex"
        >
          {showFiat && estimatedFeeFiat && (
            <Text className="text-alternative font-medium">
              {estimatedFeeFiat}
            </Text>
          )}
          <Box
            flexDirection={BoxFlexDirection.Row}
            alignItems={BoxAlignItems.Center}
            gap={1}
            className="flex"
          >
            <Text className="text-default font-medium">
              {estimatedFeeNative}
            </Text>
            <AvatarToken
              size={AvatarTokenSize.Xs}
              src={source}
              name={nativeCurrency}
            />
            {nativeCurrency && (
              <Text className="text-default font-medium">{nativeCurrency}</Text>
            )}
          </Box>
        </Box>
      </Box>
    </ConfirmInfoRow>
  );
};

type SpeedRowProps = {
  chainId: string;
  networkClientId?: string;
  maxFeePerGas?: string;
  maxPriorityFeePerGas?: string;
  userFeeLevelOverride?: string;
};

const SpeedRow = ({
  chainId,
  networkClientId,
  maxFeePerGas,
  maxPriorityFeePerGas,
  userFeeLevelOverride,
}: SpeedRowProps) => {
  const t = useI18nContext();
  return (
    <ConfirmInfoRow label={t('speed')} data-testid="gas-fee-details-speed">
      <Box alignItems={BoxAlignItems.Center} className="flex">
        <GasTiming
          chainId={chainId}
          networkClientId={networkClientId}
          maxFeePerGas={maxFeePerGas}
          maxPriorityFeePerGas={maxPriorityFeePerGas}
          userFeeLevelOverride={userFeeLevelOverride}
        />
      </Box>
    </ConfirmInfoRow>
  );
};

type GasFeesSectionProps = {
  transaction: TransactionMeta;
};

const GasFeesSection = ({ transaction }: GasFeesSectionProps) => {
  const { openGasFeeModal } = useGasFeeModalContext();
  const { chainId } = transaction;

  const showFiat = useSelector((state) => getShouldShowFiat(state, chainId));

  const { maxFeePerGas, maxPriorityFeePerGas } = useEIP1559TxFees(transaction);
  const { estimatedFeeFiat, estimatedFeeNative } =
    useFeeCalculations(transaction);

  return (
    <ConfirmInfoSection data-testid="cancel-speedup-section">
      <NetworkFeeRow
        estimatedFeeNative={estimatedFeeNative}
        estimatedFeeFiat={estimatedFeeFiat}
        showFiat={showFiat}
        onEdit={() => openGasFeeModal()}
        chainId={transaction.chainId}
      />

      <SpeedRow
        chainId={transaction.chainId}
        networkClientId={transaction.networkClientId}
        maxFeePerGas={maxFeePerGas}
        maxPriorityFeePerGas={maxPriorityFeePerGas}
        userFeeLevelOverride={transaction.userFeeLevel}
      />
    </ConfirmInfoSection>
  );
};

const DescriptionSection = ({ isCancel }: { isCancel: boolean }) => {
  const t = useI18nContext();
  return (
    <Box marginTop={4}>
      <Text
        variant={TextVariant.BodySm}
        color={TextColor.TextAlternative}
        className="text-center"
      >
        {isCancel
          ? t('cancelTransactionDescription')
          : t('speedUpTransactionDescription')}
      </Text>
    </Box>
  );
};

const ConfirmButton = ({
  onClick,
  disabled,
  hasInsufficientBalance,
}: {
  onClick: () => void;
  disabled?: boolean;
  hasInsufficientBalance?: boolean;
}) => {
  const t = useI18nContext();
  return (
    <Button
      variant={ButtonVariant.Primary}
      className="w-full"
      onClick={onClick}
      disabled={disabled}
      data-testid="cancel-speedup-confirm-button"
    >
      {hasInsufficientBalance ? t('insufficientFundsSend') : t('confirm')}
    </Button>
  );
};

type TransactionModalContextType = {
  closeModal: (modalNames: string[]) => void;
  openModal: (modalName: string) => void;
  currentModal: string;
};

type CancelSpeedupModalProps = {
  mode: EditGasModes;
  onClose: () => void;
  dataTestId?: string;
  effectiveTransaction: TransactionMeta;
  isInitialGasReady: boolean;
  cancelTransaction: () => void;
  speedUpTransaction: () => void;
  submitTransaction: (action: () => void, isCancel: boolean) => Promise<void>;
};

const GasFeesSectionSkeleton = () => (
  <ConfirmInfoSection data-testid="cancel-speedup-section-loading">
    <Box flexDirection={BoxFlexDirection.Column} gap={3} padding={2}>
      <Skeleton height={16} width="100%" />
      <Skeleton height={16} width="60%" />
    </Box>
  </ConfirmInfoSection>
);

const CancelSpeedupModal = ({
  mode,
  onClose,
  dataTestId,
  effectiveTransaction,
  isInitialGasReady,
  cancelTransaction,
  speedUpTransaction,
  submitTransaction,
}: CancelSpeedupModalProps) => {
  const t = useI18nContext();
  const isCancel = mode === EditGasModes.cancel;

  const selectedAccount = useSelector(getSelectedAccount);

  const hasEnoughBalance = isInitialGasReady
    ? isBalanceSufficient({
        amount: '0x0',
        gasTotal: getMaximumGasTotalInHexWei({
          gasLimit:
            effectiveTransaction.txParams?.gas ??
            effectiveTransaction.txParams?.gasLimit,
          gasPrice: effectiveTransaction.txParams?.gasPrice,
          maxFeePerGas: effectiveTransaction.txParams?.maxFeePerGas,
        }),
        balance: selectedAccount?.balance,
      })
    : true;

  const handleSubmit = () => {
    const action = isCancel ? cancelTransaction : speedUpTransaction;
    submitTransaction(action, isCancel);
  };

  return (
    <Modal
      isOpen
      onClose={onClose}
      data-testid={dataTestId}
      isClosedOnOutsideClick={false}
    >
      <ModalOverlay />
      <ModalContent>
        <ModalHeader onClose={onClose}>
          {isCancel
            ? t('cancelTransactionTitle')
            : t('speedUpTransactionTitle')}
        </ModalHeader>
        <Box padding={4}>
          {isInitialGasReady ? (
            <GasFeesSection transaction={effectiveTransaction} />
          ) : (
            <GasFeesSectionSkeleton />
          )}
          <DescriptionSection isCancel={isCancel} />
        </Box>
        <ModalFooter>
          <ConfirmButton
            onClick={handleSubmit}
            disabled={!isInitialGasReady || !hasEnoughBalance}
            hasInsufficientBalance={isInitialGasReady && !hasEnoughBalance}
          />
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
};

type CancelSpeedupContentProps = {
  transaction: TransactionMeta;
  editGasMode: EditGasModes;
  onClose: () => void;
  submitTransaction: (action: () => void, isCancel: boolean) => Promise<void>;
};

const CancelSpeedupContent = ({
  transaction,
  editGasMode,
  onClose,
  submitTransaction,
}: CancelSpeedupContentProps) => {
  const { currentModal } =
    useTransactionModalContext() as TransactionModalContextType;
  const appIsLoading = useSelector(getAppIsLoading);

  const {
    effectiveTransaction,
    gasFeeEstimates,
    isGasEstimatesLoading,
    cancelTransaction,
    speedUpTransaction,
    updateTransactionToTenPercentIncreasedGasFee,
    updateTransactionUsingEstimate,
  } = useCancelSpeedupGasState(transaction, editGasMode);

  const { isInitialGasReady } = useCancelSpeedupInitialGas({
    effectiveTransaction,
    gasFeeEstimates,
    isGasEstimatesLoading,
    updateTransactionUsingEstimate,
    updateTransactionToTenPercentIncreasedGasFee,
    appIsLoading,
    currentModal,
  });

  return (
    <GasFeeModalContextProvider
      transactionMeta={effectiveTransaction}
      editGasMode={editGasMode}
    >
      <>
        <GasFeeModalWrapper />
        <CancelSpeedupModal
          mode={editGasMode}
          onClose={onClose}
          dataTestId="speed-up-and-cancel-modal"
          effectiveTransaction={effectiveTransaction}
          isInitialGasReady={isInitialGasReady}
          cancelTransaction={cancelTransaction}
          speedUpTransaction={speedUpTransaction}
          submitTransaction={submitTransaction}
        />
      </>
    </GasFeeModalContextProvider>
  );
};

type CancelSpeedupProps = {
  transaction: TransactionMeta;
  editGasMode: EditGasModes;
};

export const CancelSpeedup = ({
  transaction,
  editGasMode,
}: CancelSpeedupProps) => {
  const { currentModal, closeModal } =
    useTransactionModalContext() as TransactionModalContextType;

  const onClose = useCallback(() => {
    closeModal(['cancelSpeedUpTransaction']);
  }, [closeModal]);
  const { error, clearError, submitTransaction } =
    useCancelSpeedupActions(onClose);

  if (currentModal !== 'cancelSpeedUpTransaction') {
    if (error) {
      return (
        <CancelSpeedupErrorToast
          isCancel={error.isCancel}
          errorMessage={error.message}
          onClose={clearError}
        />
      );
    }
    return null;
  }

  return (
    <CancelSpeedupContent
      transaction={transaction}
      editGasMode={editGasMode}
      onClose={onClose}
      submitTransaction={submitTransaction}
    />
  );
};
