import React, { useCallback, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { Hex } from '@metamask/utils';
import {
  ButtonIcon,
  ButtonIconSize,
  IconName,
} from '../../../../../components/component-library';
import { IconColor } from '../../../../../helpers/constants/design-system';
import {
  selectNetworkConfigurationByChainId,
  type NetworkConfigurationsByChainIdState,
} from '../../../../../../shared/lib/selectors/networks';

const HYPERLIQUID_EXPLORER_URL = 'https://app.hyperliquid.xyz/explorer';

type BlockExplorerLinkProps = {
  chainId: Hex;
  hash: string | undefined;
  isHyperliquid?: boolean;
};

function getBlockExplorerTxUrl(
  blockExplorerUrl: string | undefined,
  txHash: string | undefined,
): string | undefined {
  if (blockExplorerUrl && txHash) {
    const rootUrl = blockExplorerUrl.replace(/\/$/u, '');
    return `${rootUrl}/tx/${txHash}`;
  }
  return undefined;
}

export function BlockExplorerLink({
  chainId,
  hash,
  isHyperliquid = false,
}: BlockExplorerLinkProps) {
  const networkConfiguration = useSelector(
    (state: NetworkConfigurationsByChainIdState) =>
      selectNetworkConfigurationByChainId(state, chainId),
  );

  const blockExplorerUrl = useMemo(() => {
    if (!networkConfiguration) {
      return undefined;
    }

    if (isHyperliquid) {
      return HYPERLIQUID_EXPLORER_URL;
    }

    const { defaultBlockExplorerUrlIndex, blockExplorerUrls } =
      networkConfiguration;

    if (defaultBlockExplorerUrlIndex === undefined) {
      return undefined;
    }

    return blockExplorerUrls?.[defaultBlockExplorerUrlIndex];
  }, [isHyperliquid, networkConfiguration]);

  const explorerTxUrl = getBlockExplorerTxUrl(blockExplorerUrl, hash);

  const handleClick = useCallback(() => {
    if (explorerTxUrl) {
      global.platform.openTab({ url: explorerTxUrl });
    }
  }, [explorerTxUrl]);

  if (!explorerTxUrl) {
    return null;
  }

  return (
    <ButtonIcon
      iconName={IconName.Export}
      size={ButtonIconSize.Sm}
      color={IconColor.iconAlternative}
      ariaLabel="View on block explorer"
      onClick={handleClick}
      data-testid="block-explorer-link"
    />
  );
}
