/* eslint-disable @typescript-eslint/naming-convention */
import React, { useMemo } from 'react';
import { useSelector } from 'react-redux';
import {
  TransactionMeta,
  TransactionStatus,
  TransactionType,
} from '@metamask/transaction-controller';
import { Hex } from '@metamask/utils';
import { Box, Text } from '../../../../../components/component-library';
import {
  AlignItems,
  BackgroundColor,
  Display,
  FlexDirection,
  JustifyContent,
  TextColor,
  TextVariant,
} from '../../../../../helpers/constants/design-system';
import { useI18nContext } from '../../../../../hooks/useI18nContext';
import { useTransactionDetails } from '../transaction-details-context';
import { formatTransactionDateTime } from '../utils';
import { getTransactions } from '../../../../../selectors/transactions';
import { getTokenByAccountAndAddressAndChainId } from '../../../../../selectors/assets';
import {
  selectNetworkConfigurationByChainId,
  type NetworkConfigurationsByChainIdState,
} from '../../../../../../shared/lib/selectors/networks';
import { useTokenWithBalance } from '../../../hooks/tokens/useTokenWithBalance';
import { BlockExplorerLink } from '../block-explorer-link';
import { TransactionStatusIcon } from '../transaction-status-icon';
import { hasTransactionType } from '../../../../../../shared/lib/transactions.utils';

const RELAY_DEPOSIT_TYPES = [
  TransactionType.relayDeposit,
  TransactionType.perpsRelayDeposit,
  TransactionType.predictRelayDeposit,
];

type TranslateFunction = (key: string, args?: string[]) => string;

export function TransactionDetailsSummary() {
  const t = useI18nContext() as TranslateFunction;
  const { transactionMeta } = useTransactionDetails();
  const allTransactions = useSelector(getTransactions);
  const { requiredTransactionIds, metamaskPay } = transactionMeta;

  const hasRequiredTransactions =
    requiredTransactionIds && requiredTransactionIds.length > 0;

  const requiredTransactions = useMemo(() => {
    if (!hasRequiredTransactions) {
      return [];
    }

    return requiredTransactionIds
      .map((id) =>
        (allTransactions as TransactionMeta[]).find((tx) => tx.id === id),
      )
      .filter((tx): tx is TransactionMeta => tx !== undefined);
  }, [hasRequiredTransactions, requiredTransactionIds, allTransactions]);

  const transactions = useMemo(() => {
    return [...requiredTransactions, transactionMeta];
  }, [requiredTransactions, transactionMeta]);

  const payTokenAddress = metamaskPay?.tokenAddress as Hex | undefined;
  const payTokenChainId = metamaskPay?.chainId as Hex | undefined;

  return (
    <Box
      display={Display.Flex}
      flexDirection={FlexDirection.Column}
      gap={3}
      data-testid="transaction-details-summary"
    >
      <Text color={TextColor.textAlternative}>{t('summary')}</Text>
      <Box
        display={Display.Flex}
        flexDirection={FlexDirection.Column}
        paddingLeft={2}
      >
        {transactions.map((tx, index) => (
          <TransactionSummaryLine
            key={tx.id}
            transactionMeta={tx}
            relatedTransactions={requiredTransactions}
            payTokenAddress={payTokenAddress}
            payTokenChainId={payTokenChainId}
            isLast={index === transactions.length - 1}
          />
        ))}
      </Box>
    </Box>
  );
}

function TransactionSummaryLine({
  transactionMeta,
  relatedTransactions,
  payTokenAddress,
  payTokenChainId,
  isLast,
}: {
  transactionMeta: TransactionMeta;
  relatedTransactions: TransactionMeta[];
  payTokenAddress: Hex | undefined;
  payTokenChainId: Hex | undefined;
  isLast: boolean;
}) {
  const { type } = transactionMeta;

  if (hasTransactionType(transactionMeta, RELAY_DEPOSIT_TYPES)) {
    return (
      <RelayDepositSummaryLine
        transactionMeta={transactionMeta}
        tokenAddress={payTokenAddress}
        tokenChainId={payTokenChainId}
      />
    );
  }

  if (type === TransactionType.tokenMethodApprove) {
    return (
      <ApprovalSummaryLine transactionMeta={transactionMeta} isLast={isLast} />
    );
  }

  if (
    type === TransactionType.musdClaim ||
    type === TransactionType.musdConversion ||
    type === TransactionType.perpsDeposit ||
    type === TransactionType.perpsWithdraw
  ) {
    return (
      <ReceiveSummaryLine
        transactionMeta={transactionMeta}
        relatedTransactions={relatedTransactions}
        isLast={isLast}
      />
    );
  }

  return (
    <DefaultSummaryLine transactionMeta={transactionMeta} isLast={isLast} />
  );
}

function RelayDepositSummaryLine({
  transactionMeta,
  tokenAddress,
  tokenChainId,
}: {
  transactionMeta: TransactionMeta;
  tokenAddress: Hex | undefined;
  tokenChainId: Hex | undefined;
}) {
  const t = useI18nContext() as TranslateFunction;
  const { chainId } = transactionMeta;

  const token = useTokenWithBalance(
    (tokenAddress ?? '0x0') as Hex,
    tokenChainId ?? chainId,
  );

  const networkConfig = useSelector(
    (state: NetworkConfigurationsByChainIdState) =>
      selectNetworkConfigurationByChainId(state, chainId),
  );

  const tokenSymbol = token?.symbol;
  const networkName = networkConfig?.name;

  const title =
    tokenSymbol && networkName
      ? t('bridgeSend', [tokenSymbol, networkName])
      : t('bridgeSendLoading');

  return (
    <SummaryLine
      chainId={chainId}
      hash={transactionMeta.hash}
      status={transactionMeta.status}
      time={transactionMeta.submittedTime ?? transactionMeta.time}
      title={title}
      isLast={false}
    />
  );
}

function ApprovalSummaryLine({
  transactionMeta,
  isLast,
}: {
  transactionMeta: TransactionMeta;
  isLast: boolean;
}) {
  const t = useI18nContext() as TranslateFunction;
  const { chainId, txParams } = transactionMeta;

  const tokenAddress = txParams?.to as Hex | undefined;

  const token = useTokenWithBalance((tokenAddress ?? '0x0') as Hex, chainId);

  const tokenSymbol = token?.symbol;

  const title = tokenSymbol
    ? t('approveToken', [tokenSymbol])
    : t('approveButtonText');

  return (
    <SummaryLine
      chainId={chainId}
      hash={transactionMeta.hash}
      status={transactionMeta.status}
      time={transactionMeta.submittedTime ?? transactionMeta.time}
      title={title}
      isLast={isLast}
    />
  );
}

const HYPERLIQUID_NETWORK_NAME = 'Hyperliquid';

function ReceiveSummaryLine({
  transactionMeta,
  relatedTransactions,
  isLast,
}: {
  transactionMeta: TransactionMeta;
  relatedTransactions: TransactionMeta[];
  isLast: boolean;
}) {
  const t = useI18nContext() as TranslateFunction;
  const { type, chainId, txParams } = transactionMeta;
  const isPerpsDeposit = type === TransactionType.perpsDeposit;
  const isMusdConversion = type === TransactionType.musdConversion;

  const targetTokenAddress = txParams?.to as Hex | undefined;

  const token = useSelector((state) =>
    targetTokenAddress && chainId
      ? getTokenByAccountAndAddressAndChainId(
          state,
          undefined,
          targetTokenAddress,
          chainId,
        )
      : null,
  );

  const networkConfig = useSelector(
    (state: NetworkConfigurationsByChainIdState) =>
      selectNetworkConfigurationByChainId(state, chainId),
  );

  const tokenSymbol = token?.symbol;

  let networkName: string | undefined;
  if (isPerpsDeposit) {
    networkName = HYPERLIQUID_NETWORK_NAME;
  } else {
    networkName = networkConfig?.name;
  }

  const title =
    tokenSymbol && networkName
      ? t('bridgeReceive', [tokenSymbol, networkName])
      : t('bridgeReceiveLoading');

  let hash: string | undefined =
    transactionMeta?.hash === '0x0' ? undefined : transactionMeta?.hash;

  if (isMusdConversion && !hash) {
    // For same-chain aggregator routes (e.g. Linea USDT/DAI), the relay
    // strategy skips polling and sets the musdConversion hash to '0x0'.
    // Fall back to the relay deposit's on-chain hash, which represents
    // the actual swap transaction where mUSD was received.
    const relayDepositTx = relatedTransactions.find((tx) =>
      hasTransactionType(tx, [TransactionType.relayDeposit]),
    );
    if (relayDepositTx?.hash && relayDepositTx.hash !== '0x0') {
      hash = relayDepositTx.hash as Hex;
    }
  }

  return (
    <SummaryLine
      chainId={chainId}
      hash={hash}
      isHyperliquid={isPerpsDeposit}
      status={transactionMeta.status}
      time={transactionMeta.submittedTime ?? transactionMeta.time}
      title={title}
      isLast={isLast}
    />
  );
}

function DefaultSummaryLine({
  transactionMeta,
  isLast,
}: {
  transactionMeta: TransactionMeta;
  isLast: boolean;
}) {
  const t = useI18nContext() as TranslateFunction;
  const { type, chainId } = transactionMeta;

  let title: string;
  switch (type) {
    case TransactionType.bridge:
      title = t('bridge');
      break;
    case TransactionType.bridgeApproval:
      title = t('bridgeApproval');
      break;
    case TransactionType.swap:
      title = t('swap');
      break;
    case TransactionType.swapApproval:
      title = t('swapApproval');
      break;
    default:
      title = t('transaction');
  }

  return (
    <SummaryLine
      chainId={chainId}
      hash={transactionMeta.hash}
      status={transactionMeta.status}
      time={transactionMeta.submittedTime ?? transactionMeta.time}
      title={title}
      isLast={isLast}
    />
  );
}

function SummaryLine({
  chainId,
  hash,
  isHyperliquid = false,
  isLast,
  status,
  time,
  title,
}: {
  chainId: Hex;
  hash: string | undefined;
  isHyperliquid?: boolean;
  isLast: boolean;
  status: TransactionStatus;
  time: number;
  title: string;
}) {
  const { time: timeString, date } = formatTransactionDateTime(time);

  return (
    <Box display={Display.Flex} flexDirection={FlexDirection.Column}>
      <Box
        display={Display.Flex}
        flexDirection={FlexDirection.Row}
        alignItems={AlignItems.center}
        justifyContent={JustifyContent.spaceBetween}
      >
        <Box
          display={Display.Flex}
          flexDirection={FlexDirection.Row}
          alignItems={AlignItems.center}
          gap={2}
        >
          <TransactionStatusIcon status={status} />
          <Text variant={TextVariant.bodyMdMedium}>{title}</Text>
        </Box>
        <BlockExplorerLink
          chainId={chainId}
          hash={hash}
          isHyperliquid={isHyperliquid}
        />
      </Box>
      <Box display={Display.Flex} flexDirection={FlexDirection.Row}>
        <Box
          display={Display.Flex}
          justifyContent={JustifyContent.center}
          style={{ width: '16px' }}
        >
          {!isLast && (
            <Box
              backgroundColor={BackgroundColor.iconAlternative}
              style={{
                width: '2px',
                minHeight: '16px',
              }}
            />
          )}
        </Box>
        <Text
          variant={TextVariant.bodySm}
          color={TextColor.textAlternative}
          paddingLeft={2}
          paddingBottom={isLast ? 0 : 2}
        >
          {timeString} • {date}
        </Text>
      </Box>
    </Box>
  );
}
